  function looks(raw) { const s = String(raw || '').trim(); if (!local(s) || /[*<>|\n]/.test(s) || /^v?\d+(?:\.\d+)+(?:[-\w]*)?$/.test(s)) return false; const p = norm(s); return /\.[a-z\d]{1,12}$/i.test(p) || /^(\/home\/user\/|~\/|\.\/|\/workspace\/)/.test(s); }
