    document.head.appendChild(s);
    setTimeout(() => { if (!window.grecaptcha?.enterprise?.execute) { loading = null; s.remove(); rej(new Error('reCAPTCHA 加载超时（检查代理能否访问 google.com）')); } }, 20000);
