        const isCrown = !isOpen && /opus|fable|gpt-6|6\.1|sol\b|astra\b|luna\b|argon|barium/i.test(txt);
        const isClosed = !isOpen && (isCrown || /sonnet|haiku|claude|gpt-5|gpt-4|o1|o3|o4|gemini|grok|terra/i.test(txt));
