const modelLabel = m => m ? (m.pendingConfirm ? '请继续沟通' : (m.name ? ((typeof cardName === 'function' ? cardName(m.name) : Strength.canon(m.name)) || m.name) + (m.partial ? '?' : '') : '')) : '';

// ---------- 标签页 ----------
