// ---------- 发送键旁的抽卡按钮（目标厂商 + 张数 + 开始/停止，弹出 256px 面板）----------
const GPop = {
  btn() {
    const b = h('button', { class: 'gbtn2', type: 'button', onclick: e => { e.stopPropagation(); if (b._rvSkip && Date.now() - b._rvSkip < 500) return; if (b.hasAttribute('data-cap')) { GPop.captcha(); return; } this.toggle(b); } });
    this.paint(b); Revolver.attach(b); return b;
  },
  // 抽卡遇到人机验证：按钮变成「验」，点一下直接弹出验证，完成后自动继续
  captcha() {
    if (Gacha.solving) { toast('验证窗口已经打开'); return; }
    Gacha.solveCaptcha().then(() => toast('已完成人机验证，继续抽卡')).catch(e => toast('人机验证没有完成：' + describe(e), 'err'));
  },
  capEl(b, on, solving) {
    b.toggleAttribute('data-cap', !!on);
    if (!on) return false;
    b.title = solving ? '正在人机验证…' : '抽卡遇到人机验证：点一下完成验证，完成后自动继续抽卡';
    b.replaceChildren(h('span', { class: 'g-cap' + (solving ? ' ing' : '') }, '验'));
    return true;
  },
  paint(b) {
    if (!b) return;
    const s0 = Gacha.settings(), r = Gacha.run, busy = Gacha.busy();
    if (this.capEl(b, Gacha.needCaptcha(), Gacha.solving)) { b.dataset.running = 'true'; b.removeAttribute('data-empty'); return; }
    // 抽卡中：按钮显示这一轮抽卡的目标（开始时定下）；左轮 / 面板换的厂商只影响侧栏排序
    const s = busy && r?.settings ? { ...s0, vendor: r.settings.vendor || '', targetName: r.settings.targetName || '' } : s0, v = Gacha.vendorBy(s.vendor);
    const total = r?.settings?.endless ? '∞' : (r?.settings?.maxAttempts || s.maxAttempts), done = r?.completed || 0;
    b.dataset.running = String(busy); b.toggleAttribute('data-empty', !s.vendor);
    b.title = busy ? `抽卡中 ${done}/${total}${r.phase ? ' · ' + r.phase : ''}${(s0.vendor || '') !== (s.vendor || '') ? ' · 侧栏排序：' + (s0.targetName || '不限') : ''} · 点击查看（滚轮 / 上下滑动可换侧栏排序的厂商，不影响抽卡）` : '目标模型：' + (s.targetName || '不限') + ' · 点击设置并抽卡（Ctrl+G）';
    const last = (r?.attempts || []).filter(a => a.model && a.done).at(-1), lvid = last ? Brand.of(last.model) : '';
    b.replaceChildren(...K(
      busy ? h('span', { class: 'g-ring', style: { '--p': total === '∞' ? 100 : Math.round(done / total * 100) } }, v ? VIcon.el(v.id, 14) : icon('slot', 'g-any')) : v ? VIcon.el(v.id, 14) : s.vendor === 'custom' ? h('span', { class: 'g-k' }, '#') : null,
      h('span', { class: 'g-name' }, s.targetName || '不限'),
      busy ? h('span', { class: 'g-prog' }, done + '/' + total) : icon('chev', 'g-chev'),
      busy ? h('i', { class: 'g-bar', style: { width: (total === '∞' ? 100 : Math.min(100, done / total * 100)) + '%' } }) : null,
      r && !busy && r.status === 'stopped' && r.code && !['RELOADED', 'CANCEL'].includes(r.code) ? h('i', { class: 'g-dot' }) : null));
    if (busy && lvid && last.no !== b._land) { b._land = last.no; b.classList.remove('land'); void b.offsetWidth; b.classList.add('land'); b.classList.toggle('hit', last.verdict === 'hit'); }
  },
};
// 账号菜单里的抽卡按钮：和发送键旁的抽卡按钮一样只是一个图标（厂商图标 / 进度环），功能完全一样：
// 点一下弹出同一个抽卡面板（张数、目标厂商、归档黑名单、提示词都能改），滚轮 / 长按弹出左轮选厂商；
// 面板里按 START 就在后台抽这个账号（不打开窗口），进度显示在图标的进度环和账号那一行的「抽卡中 n/N」上
GPop.acctBtn = function (a, isCur) {
  const b = h('button', { class: 'gbtn2 gacct', type: 'button', 'data-acct': a.id, 'data-cur': isCur ? '1' : '0', 'data-name': emailUser(a) });
  b.onclick = e => { e.stopPropagation(); e.preventDefault(); if (b._rvSkip && Date.now() - b._rvSkip < 500) return; if (b.hasAttribute('data-cap')) { GPop.acctCaptcha(b); return; } GPop.toggle(b); };
  if (!isCur) GPop.remote.set(a.id, a.status?.gacha || null);
  GPop.paintAcct(b, GPop.acctState(a.id, isCur)); Revolver.attach(b); return b;
};
GPop.remote = new Map();
GPop.acctState = function (id, isCur) {
  if (isCur) {
    const r = Gacha.run, s = Gacha.settings();let last;for(let i=(r?.attempts?.length||0)-1;i>=0;i--){const x=r.attempts[i];if(x.model&&x.done){last=x;break;}}
    return { busy: Gacha.busy(), cap: Gacha.needCaptcha(), done: r?.completed || 0, total: r?.settings?.endless ? '∞' : (r?.settings?.maxAttempts || s.maxAttempts), hits: (r?.hits || []).length, phase: r?.phase || '', last: last?.model || '', status: r?.status || '',
      err: r && !Gacha.busy() && r.status === 'stopped' && r.code && !['RELOADED', 'CANCEL'].includes(r.code) ? r.reason : '',
      log: (r?.attempts || []).slice(-12).map(x => ({ no: x.no, draw: x.draw, at: x.at, model: x.model || '', tier: x.tier || '', verdict: x.verdict || '', archived: !!x.archived, note: x.note || '' })) };
  }
  const g = GPop.remote.get(id) || {};
  return { busy: !!g.busy, cap: !!g.busy && !!g.cap, done: g.done || 0, total: g.total || Gacha.settings(id).maxAttempts, hits: g.hits || 0, phase: g.phase || '', last: g.last || '', err: g.err || '', status: g.status || '', log: Array.isArray(g.log) ? g.log : [] };
};
// 其他账号的「验」：电脑 = 把那个账号的窗口拿到前面并直接弹出验证；手机 = 切到那个账号（再点一下它的「验」）
GPop.acctCaptcha = async function (b) {
  if (b.dataset.cur === '1') { GPop.captcha(); return; }
  const id = b.dataset.acct, name = b.dataset.name || '这个账号';
  document.querySelectorAll('.menu:not(.anc-gh).amenu,.lpick').forEach(x => { try { x.remove(); } catch {} });
  const r = Host.gachaAccount ? await Host.gachaAccount(id, 'captcha').catch(e => ({ error: e.message })) : { error: 'x' };
  if (r?.ok) { toast(name + '：已打开验证窗口'); return; }
  toast('正在切换到 ' + name + '，点抽卡按钮上的「验」完成验证'); Host.openAccount(id);
};
GPop.paintAcct = function (b, g) {
  const s = Gacha.settings(b.dataset.cur === '1' ? null : b.dataset.acct), v = Gacha.vendorBy(s.vendor), total = g.total || s.maxAttempts, done = g.done || 0;
  const paintKey=JSON.stringify([g.busy,g.cap,g.done,g.total,g.hits,g.phase,g.err,s.vendor,s.customKeyword,s.targetName,s.maxAttempts,b.dataset.name,Gacha.solving]);
  if(b._acctPaint===paintKey)return;b._acctPaint=paintKey;
  if (GPop.capEl(b, g.cap, b.dataset.cur === '1' && Gacha.solving)) { b.dataset.running = 'true'; b.removeAttribute('data-empty'); b.title = (b.dataset.cur === '1' ? '' : (b.dataset.name || '') + ' · ') + '抽卡遇到人机验证：点一下完成验证'; const tag = b.closest('.arow-w')?.querySelector('.gtag'); if (tag) { tag.hidden = false; tag.classList.add('on'); tag.textContent = '抽卡中 ' + done + '/' + total + ' · 需要人机验证'; } return; }
  b.dataset.running = String(!!g.busy); b.toggleAttribute('data-empty', !s.vendor);
  b.title = (b.dataset.cur === '1' ? '' : (b.dataset.name || '') + ' · ') + (g.busy ? `抽卡中 ${done}/${total}${g.hits ? ' · 命中 ' + g.hits : ''}${g.phase ? ' · ' + g.phase : ''} · 点击查看` : (g.err ? '上次：' + g.err + '\n' : '') + '目标模型：' + (s.targetName || '不限') + ' · 点击设置并在后台抽卡');
  const pct = total === '∞' ? 100 : Math.min(100, Math.round(done / (total || 1) * 100));
  b.replaceChildren(...K(
    g.busy ? h('span', { class: 'g-ring', style: { '--p': pct } }, v ? VIcon.el(v.id, 14) : icon('slot', 'g-any')) : v ? VIcon.el(v.id, 14) : s.vendor === 'custom' ? h('span', { class: 'g-k' }, '#') : null,
    !g.busy && g.err ? h('i', { class: 'g-dot' }) : null));
  // 账号那一行：抽卡中 n/N
  const tag = b.closest('.arow-w')?.querySelector('.gtag');
  if (tag) {
    // 账号卡片第四行：抽卡进度（没在抽时显示上次结果 / 未运行）
    tag.hidden = false; tag.classList.toggle('on', !!g.busy); tag.classList.toggle('err', !g.busy && !!g.err);
    tag.textContent = g.busy ? '抽卡中 ' + done + '/' + total + (g.hits ? ' · 命中 ' + g.hits : '') + (g.phase ? ' · ' + g.phase : '')
      : g.err ? '抽卡已停：' + g.err : (g.done ? '上次抽卡 ' + g.done + '/' + total + (g.hits ? ' · 命中 ' + g.hits : '') : '抽卡 未运行');
  }
};
// 把本窗口的抽卡进度报给宿主（账号菜单里其他窗口显示用）
GPop.report = function () {
  clearTimeout(GPop.rt); GPop.rt = setTimeout(() => { const g = GPop.acctState('', true); Host.noteAccount?.({ gacha: g })?.catch?.(() => {}); }, 700);
};
Bus.on('gacha', () => GPop.report());
Bus.on('gacha', () => { clearTimeout(GPop.t); GPop.t = setTimeout(() => { document.querySelectorAll('.gbtn2:not([data-acct])').forEach(b => GPop.paint(b)); if (GPop.isOpen() && !GPop.root.activeElement?.matches?.('input,textarea')) GPop.fill(); }, 80); });

// ---------- 侧栏卡片放大（鼠标最近的卡片和上下各一张向右探出）----------
const Mag = {
  bind(list) {
    let raf = 0, ev = null, act = new Set();
    const reset = () => { for (const a of act) a.style.removeProperty('--mag'); act = new Set(); list.classList.remove('mag-on'); };
    list.addEventListener('mousemove', e => { ev = e; if (!raf) raf = requestAnimationFrame(() => {
      raf = 0; if (Prefs.cardMag === false || matchMedia('(prefers-reduced-motion: reduce)').matches) return;
      const cards = [...list.querySelectorAll('.card')], y = ev.clientY; let ni = -1, nd = Infinity;
      cards.forEach((c, i) => { const r = c.getBoundingClientRect(), d = Math.abs(r.top + r.height / 2 - y); if (d < nd) { nd = d; ni = i; } });
      const next = new Set(); list.classList.add('mag-on');
      if (ni >= 0 && nd < 40) for (const [k, m] of [[0, 1.06], [-1, 1.025], [1, 1.025]]) { const c = cards[ni + k]; if (c) { c.style.setProperty('--mag', m); next.add(c); } }
      for (const a of act) if (!next.has(a)) a.style.removeProperty('--mag'); act = next;
    }); });
    list.addEventListener('mouseleave', reset);
  },
};

// ---- file-export.js ----
// Text exports must use the native writer in WebView; blob/download anchors are browser-only.
const FileExport = {
  busy:false,
  async blob(blob,name,mime=blob.type||'application/octet-stream') {
    if (Host.platform !== 'android') { saveBlob(new Blob([blob],{type:mime}),name); return {requested:true}; }
    if (!Host.downloadStart || !Host.downloadChunk || !Host.downloadFinish) throw Error('当前 Android 宿主不支持二进制下载，请更新客户端');
    if (this.busy) throw Error('已有文件正在保存，请稍候');
    if (blob.size > 160*1024*1024) throw Error('文件超过 160MB 保存上限，请使用网页版下载');
    this.busy=true; let id;
    try {
      const start=await Host.downloadStart(name,mime,blob.size); if (!start?.ok||!start.id) throw Error(start?.error||'无法创建下载文件'); id=start.id;
      for(let at=0;at<blob.size;at+=512*1024) {
        const b64=await new Promise((resolve,reject)=>{const f=new FileReader();f.onload=()=>resolve(String(f.result).split(',')[1]||'');f.onerror=()=>reject(Error('无法读取文件分块'));f.readAsDataURL(blob.slice(at,at+512*1024));});
        const r=await Host.downloadChunk(id,b64); if(!r?.ok)throw Error(r?.error||'文件分块未保存');
      }
      const result=await Host.downloadFinish(id); if(!result?.ok)throw Error(result?.error||'文件未完整保存'); id=null; toast('已保存：'+result.path);
      if(result.share) void Dialog.open((box,done)=>{
        box.append(h('div',{class:'dlg-t'},'工作区文件已保存'),h('p',{},result.path),h('div',{class:'dlg-row'},
          Host.openFile?h('button',{class:'btn',onclick:()=>Host.openFile(result.share,mime)},'用系统应用打开'):null,
          Host.shareFile?h('button',{class:'btn ghost',onclick:()=>Host.shareFile(result.share,mime)},'分享文件'):null,
          h('button',{class:'btn ghost',onclick:()=>done(null)},'关闭')));
      });
      return result;
    } finally { this.busy=false; if(id)try{await Host.downloadCancel?.(id);}catch{} }
  },
  async write(text,name,mime='application/json'){
    const native=Host.platform==='android'||!!Host.saveFile;
    if(native){
      if(typeof Host.saveFile!=='function')throw Error('当前宿主不支持保存文件，请使用复制内容或更新客户端');
      const r=await Host.saveFile(name,mime,text);
      if(r?.canceled)return {canceled:true};
      if(!r?.ok||!r.path)throw Error(r?.error||'宿主未确认文件已保存');
      return r;
    }
    saveBlob(new Blob([text],{type:mime}),name);
    return {requested:true,path:'浏览器下载目录 / '+name};
  },
  async text(text,name,mime='application/json'){
    if(this.busy){toast('正在保存，请稍候');return {busy:true};}
    this.busy=true;let result;
    try{toast('正在保存…');await PanelWork.frame();result=await this.write(String(text),name,mime);}
    catch(e){result={error:describe(e)};}
    finally{this.busy=false;}
    if(result.canceled){toast('已取消保存');return result;}
    if(result.requested){toast('已请求浏览器下载：'+name);return result;}
    if(result.error)toast('导出未保存：'+result.error,'err');else toast('已保存：'+result.path);
    void Dialog.open((box,done)=>{
      box.append(h('div',{class:'dlg-t'},result.error?'导出未保存':'文件已保存'),h('p',{},result.error||result.path));
      const actions=h('div',{class:'dlg-row'});
      if(result.error)actions.append(h('button',{class:'btn',onclick:()=>{done(null);void this.text(text,name,mime);}},'重试保存'));
      if(result.share&&Host.shareFile)actions.append(h('button',{class:'btn',onclick:async()=>{try{const ok=await Host.shareFile(result.share,mime);if(!ok)toast('无法打开分享，请在下载目录中选择文件','err');}catch(e){toast(describe(e),'err');}}},'分享文件'));
      if(result.path&&Host.showFile)actions.append(h('button',{class:'btn ghost',onclick:()=>Promise.resolve(Host.showFile(result.path)).catch(e=>toast(describe(e),'err'))},'打开位置'));
      actions.append(h('button',{class:'btn ghost',onclick:()=>copyText(String(text))},'复制 JSON'));
      if(String(text).length<=512000)actions.append(h('button',{class:'btn ghost',onclick:e=>{e.currentTarget.disabled=true;box.insertBefore(h('textarea',{class:'fp-report',readOnly:true,style:{width:'100%',height:'180px'},onclick:e=>e.target.select()},String(text)),actions);}},'显示内容'));
      actions.append(h('button',{class:'btn',onclick:()=>done(null)},'关闭'));box.append(actions);
    });
    return result;
  },
};

// ---- chat-export.js ----
// 导出当前对话：完整内容（正文 / 思考 / 工具调用含 bash 命令、stdout、stderr、退出码 / 附件 / 错误）→ Markdown，存到用户选择的文件夹
const ChatExport = {
  busy: false,
  // 代码块围栏要比内容里最长的连续反引号还长，否则内容里的 ``` 会把块截断
  fence(text, lang = '') {
    const s = String(text ?? ''), n = Math.max(3, ...[...s.matchAll(/`+/g)].map(m => m[0].length + 1));
    const f = '`'.repeat(n); return f + lang + '\n' + s.replace(/\n$/, '') + '\n' + f;
  },
  when(m) {
    const v = m?.createdAt || m?.created_at || m?.timestamp || m?.at; if (!v) return '';
    const d = new Date(typeof v === 'number' && v < 1e12 ? v * 1000 : v); if (isNaN(d)) return '';
    const p = x => String(x).padStart(2, '0');
    return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`;
  },
  quote(text) { return String(text ?? '').replace(/\n$/, '').split('\n').map(l => '> ' + l).join('\n'); },
  json(v) { if (typeof v === 'string') return v; try { return JSON.stringify(v, null, 2); } catch { return String(v); } },
  toolInput(p) { return p.input ?? (p.inputText ? (() => { try { return JSON.parse(p.inputText); } catch { return p.inputText; } })() : undefined); },
  isShell(name) { return /^(bash|shell|sh|run_command|run_shell|execute_command|terminal|exec|command)$/i.test(name); },
  tool(p) {
    const name = p.toolName || String(p.type || '').replace(/^tool-/, '') || '工具';
    const inp = this.toolInput(p), out = [], o = p.output;
    const st = p.state === 'output-available' ? (o?.exit_code != null && o.exit_code !== 0 ? '失败' : '完成') : p.state === 'output-error' ? '出错' : p.state === 'output-denied' ? '已拒绝' : '未完成';
    out.push(`#### 🔧 ${name} · ${st}`);
    if (inp !== undefined) {
      const cmd = inp && typeof inp === 'object' ? inp.command ?? inp.cmd ?? inp.script : null;
      if (typeof cmd === 'string' && this.isShell(name)) {
        out.push(this.fence(cmd, 'bash'));
        const rest = { ...inp }; delete rest.command; delete rest.cmd; delete rest.script;
        if (Object.keys(rest).length) out.push('参数：', this.fence(this.json(rest), 'json'));
      } else if (inp && typeof inp === 'object' && typeof inp.content === 'string' && (inp.path || inp.file_path)) {
        // 写文件：路径 + 文件内容
        const fp = inp.path || inp.file_path, ext = (String(fp).match(/\.([\w]+)$/) || [])[1] || '';
        const rest = { ...inp }; delete rest.content;
        out.push('参数：', this.fence(this.json(rest), 'json'), '内容：', this.fence(inp.content, ext));
      } else out.push('输入：', this.fence(this.json(inp), typeof inp === 'string' ? '' : 'json'));
    }
    if (o !== undefined) {
      if (o && typeof o === 'object' && ('stdout' in o || 'stderr' in o)) {
        if (o.stdout) out.push('stdout：', this.fence(o.stdout, 'text'));
        if (o.stderr) out.push('stderr：', this.fence(o.stderr, 'text'));
        const meta = [o.exit_code != null ? 'exit ' + o.exit_code : '', o.status || '', o.duration_ms != null ? (o.duration_ms / 1000).toFixed(1) + 's' : '', o.stdout_truncated || o.stderr_truncated ? '输出已被截断' : ''].filter(Boolean);
        if (meta.length) out.push('`' + meta.join(' · ') + '`');
        const rest = { ...o }; for (const k of ['stdout', 'stderr', 'exit_code', 'status', 'duration_ms', 'stdout_truncated', 'stderr_truncated']) delete rest[k];
        if (Object.keys(rest).length) out.push('其他输出：', this.fence(this.json(rest), 'json'));
      } else out.push('输出：', this.fence(this.json(o), typeof o === 'string' ? 'text' : 'json'));
    }
    if (p.errorText) out.push('错误：', this.fence(p.errorText, 'text'));
    return out.join('\n\n');
  },
  part(p) {
    if (!p || typeof p !== 'object') return '';
    const t = String(p.type || '');
    if (t === 'text') return String(p.text || '').trim() ? String(p.text) : '';
    if (t === 'reasoning') return String(p.text || '').trim() ? '> 💭 **思考**\n>\n' + this.quote(p.text) : '';
    if (p.toolCallId || t.startsWith('tool-') || t === 'dynamic-tool') return this.tool(p);
    if (t === 'file') { const n = p.filename || p.name || p.mediaType || '附件'; const u = p.url && !/^data:/.test(p.url) ? p.url : ''; return `📎 附件：${u ? `[${n}](${u})` : n}${p.mediaType ? ' `' + p.mediaType + '`' : ''}`; }
    if (t === 'source-url') return `🔗 来源：[${p.title || p.url}](${p.url})`;
    if (t === 'source-document') return `📄 来源文档：${p.title || p.filename || ''}`;
    if (t === 'error') return '> ⚠️ **错误**\n>\n' + this.quote(p.errorText || p.text || this.json(p.error ?? p));
    if (t === 'step-start') return '';
    if (t === 'data-compaction' && p.data?.summary) return '> 🗜️ **上下文压缩摘要**\n>\n' + this.quote(p.data.summary);
    if (t.startsWith('data-')) return '';   // 内部状态（进度条之类），不是对话内容
    return `<!-- 未识别的内容类型：${t} -->\n` + this.fence(this.json(p), 'json');
  },
  build(chat) {
    const sid = chat.sid, title = History.byId?.(sid)?.title || chat.title || '对话', mi = Models.get?.(sid);
    const msgs = chat.messages || [], L = [];
    let tools = 0; for (const m of msgs) for (const p of m.parts || []) if (p?.toolCallId) tools++;
    L.push('# ' + String(title).replace(/\n/g, ' '), '');
    L.push('| 项目 | 内容 |', '|---|---|');
    L.push(`| 对话 ID | \`${sid}\` |`);
    if (mi?.name) L.push(`| 模型 | ${String(mi.name).replace(/\|/g, '\\|')}${mi.guess ? '（识别结果）' : ''} |`);
    L.push(`| 消息 | ${msgs.length} 条（工具调用 ${tools} 次） |`);
    if (chat.hasMore) L.push('| 注意 | 服务器还有更早的消息没读到，这份导出不完整 |');
    L.push(`| 导出时间 | ${this.when({ at: Date.now() })} |`, `| 导出工具 | Brana AI v${VERSION} |`, '');
    msgs.forEach((m, i) => {
      const who = m.role === 'user' ? '👤 用户' : m.role === 'assistant' ? '🤖 助手' : '⚙️ ' + (m.role || '系统');
      const at = this.when(m), model = m.role === 'assistant' ? (m.metadata?.model || m.model || '') : '';
      L.push('---', '', `## ${who} · #${i + 1}${model ? ' · ' + model : ''}${at ? ' · ' + at : ''}`, '');
      const body = (m.parts || []).map(p => this.part(p)).filter(Boolean);
      if (!body.length && typeof m.content === 'string' && m.content.trim()) body.push(m.content);
      if (m.failed) body.push('> ⚠️ 这条消息发送失败');
      L.push(body.length ? body.join('\n\n') : '*（空）*', '');
    });
    return L.join('\n').replace(/\n{3,}/g, '\n\n') + '\n';
  },
  name(chat) {
    const t = String(History.byId?.(chat.sid)?.title || 'chat').replace(/[\\/:*?"<>|\r\n\t]+/g, '_').trim().slice(0, 60) || 'chat';
    const d = new Date(), p = x => String(x).padStart(2, '0');
    return `${t}-${chat.sid.slice(0, 8)}-${d.getFullYear()}${p(d.getMonth() + 1)}${p(d.getDate())}-${p(d.getHours())}${p(d.getMinutes())}.md`;
  },
  // 桌面客户端：系统「另存为」窗口（自己选文件夹）；浏览器：文件选择器；安卓：系统保存
  async save(text, name) {
    if (typeof Host.saveAs === 'function') return Host.saveAs(name, 'text/markdown', text);
    if (Host.platform === 'android') return FileExport.write(text, name, 'text/markdown');
    if (typeof window.showSaveFilePicker === 'function') {
      try {
        const fh = await window.showSaveFilePicker({ suggestedName: name, types: [{ description: 'Markdown', accept: { 'text/markdown': ['.md'] } }] });
        const w = await fh.createWritable(); await w.write(new Blob([text], { type: 'text/markdown' })); await w.close(); return { ok: true, path: fh.name };
      } catch (e) { if (e?.name === 'AbortError') return { canceled: true }; }
    }
    saveBlob(new Blob([text], { type: 'text/markdown;charset=utf-8' }), name); return { ok: true, path: '浏览器下载目录 / ' + name, blob: true };
  },
  async run(chat) {
    if (!chat?.sid) { toast('先打开一个对话'); return; }
    if (this.busy) { toast('正在导出，请稍候'); return; }
    this.busy = true;
    try {
      if (chat.hasMore && typeof chat.loadAll === 'function') { toast('正在读取更早的消息…'); await chat.loadAll(); }
      const text = this.build(chat), r = await this.save(text, this.name(chat));
      if (r?.canceled) toast('已取消导出');
      else if (r?.error) toast('导出失败：' + r.error, 'err');
      else { toast('已导出：' + (r?.path || this.name(chat)) + (chat.hasMore ? '（更早的消息没读全）' : '')) }
      return r;
    } catch (e) { toast('导出失败：' + describe(e), 'err'); }
    finally { this.busy = false; }
  }
};

// ---- connectors.js ----
// Connectors（和官方 Agent 模式一样的「连接其他应用」）：
//   目录 GET /api/connectors · 状态 GET /api/connectors/status · 同步 POST /api/connectors/sync
//   连接 POST /api/connectors/<slug>/link-token → Merge Agent Handler Link（ah-cdn.merge.dev/initialize.js）弹窗授权
//   断开 DELETE /api/connectors/<slug>
//   启用的连接器在发消息时带上 enabledConnectors（和官方一样）；启用列表和官方网页共用 localStorage「agent-enabled-connectors:<userId>」
const Connectors = {
  LINK_JS: 'https://ah-cdn.merge.dev/initialize.js',
  // 官方的推荐顺序（目录接口拿不到时也能显示这几个）
  FEATURED: [['github', 'GitHub', 'Work with repos, issues, and pull requests.'], ['google_drive', 'Drive', 'Find and manage files in Google Drive.'], ['google_docs', 'Docs', 'Create, read, and edit Google Docs.'], ['notion', 'Notion', 'Look up your documents.'], ['gmail', 'Gmail', 'Connect your email account.'], ['linear', 'Linear', 'Track issues, projects, and cycles.'], ['google_calendar', 'Calendar', 'Connect your Google Calendar.']],
  SHORT: { google_drive: 'Drive', google_docs: 'Docs', google_calendar: 'Calendar' },
  catalog: null, status: null, uid: null, busy: new Set(), err: '', at: 0, loading: null,
  key() { return this.uid ? 'agent-enabled-connectors:' + this.uid : null; },
  readStore() {
    const k = this.key(); let v = null;
    if (k) try { v = JSON.parse(localStorage.getItem(k) || 'null'); } catch {}
    if (!v || typeof v !== 'object') v = { enabledSlugs: Prefs.connOn || [], acknowledgedSlugs: [] };
    return { enabledSlugs: Array.isArray(v.enabledSlugs) ? v.enabledSlugs.filter(s => typeof s === 'string') : [], acknowledgedSlugs: Array.isArray(v.acknowledgedSlugs) ? v.acknowledgedSlugs.filter(s => typeof s === 'string') : [] };
  },
  writeStore(s) { const k = this.key(); if (k) try { localStorage.setItem(k, JSON.stringify(s)); } catch {} Prefs.connOn = s.enabledSlugs; savePrefs(); },
  authOf(slug) { return (this.status || []).find(x => x.slug === slug)?.authStatus || (this.catalog || []).find(x => x.slug === slug)?.authStatus || 'disconnected'; },
  connected(slug) { return this.authOf(slug) === 'connected'; },
  enabled(slug) { return this.readStore().enabledSlugs.includes(slug); },
  // 发消息时带的：已连接且已启用的
  active() { if (!this.status) return []; return this.readStore().enabledSlugs.filter(s => this.connected(s)); },
  setEnabled(slug, on) {
    const s = this.readStore(), set = new Set(s.enabledSlugs); on ? set.add(slug) : set.delete(slug);
    if (on && !s.acknowledgedSlugs.includes(slug)) s.acknowledgedSlugs.push(slug);
    s.enabledSlugs = [...set]; this.writeStore(s); this.paint();
  },
  label(slug) { const c = (this.catalog || []).find(x => x.slug === slug); return this.SHORT[slug] || c?.displayName || (this.FEATURED.find(f => f[0] === slug) || [])[1] || slug; },
  list() {
    const cat = this.catalog?.length ? this.catalog : this.FEATURED.map(([slug, n, d]) => ({ slug, displayName: n, description: d, authStatus: this.authOf(slug) }));
    const order = this.FEATURED.map(f => f[0]);
    return [...cat].sort((a, b) => ((order.indexOf(a.slug) + 1) || 99) - ((order.indexOf(b.slug) + 1) || 99));
  },
  async j(path, opt) { const r = await api(path, { timeout: 20000, ...opt }); return r && typeof r === 'object' ? r : {}; },
  async refresh(force) {
    if (this.loading) return this.loading;
    if (!force && this.at && now() - this.at < 300000) return;
    if (typeof UI !== 'undefined' && !UI.authed) return;   // 没登录不读
    this.loading = (async () => {
      try {
        this.uid = (typeof UI !== 'undefined' && (UI.me?.id || UI.me?.user?.id)) || this.uid;   // 用已登录的用户信息，不额外请求 /api/me
        const [cat, st] = await Promise.allSettled([this.j('/api/connectors'), this.j('/api/connectors/status')]);
        if (cat.status === 'fulfilled' && Array.isArray(cat.value.connectors)) this.catalog = cat.value.connectors.filter(c => c && typeof c.slug === 'string');
        if (st.status === 'fulfilled' && Array.isArray(st.value.connectors)) this.status = st.value.connectors;
        this.err = cat.status === 'rejected' && st.status === 'rejected' ? describe(cat.reason) : ''; this.at = now();
      } finally { this.loading = null; this.paint(); }
    })();
    return this.loading;
  },
  async sync() { try { const r = await this.j('/api/connectors/sync', { method: 'POST' }); if (Array.isArray(r.connectors)) this.status = r.connectors; } catch { await this.refresh(true); } this.paint(); },
  loadLink() {
    if (window.AgentHandlerLink) return Promise.resolve();
    if (this.linkP) return this.linkP;
    this.linkP = new Promise((res, rej) => {
      const s = document.createElement('script'); s.src = this.LINK_JS; s.async = true;
      s.onload = () => window.AgentHandlerLink ? res() : rej(Error('授权组件没有加载成功'));
      s.onerror = () => { s.remove(); rej(Error('授权组件加载失败（ah-cdn.merge.dev 连不上，检查代理）')); };
      document.head.append(s);
    }).finally(() => { if (!window.AgentHandlerLink) this.linkP = null; });
    return this.linkP;
  },
  async connect(slug) {
    if (this.busy.has(slug)) return; this.busy.add(slug); this.paint();
    let finished = false;
    const end = async ok => {
      if (finished) return; finished = true;
      if (ok) { await this.sync(); if (this.connected(slug)) { this.setEnabled(slug, true); toast(this.label(slug) + ' 已连接，在对话里提到「' + this.label(slug) + '」就能用'); } else toast(this.label(slug) + ' 没有连接成功', 'err'); }
      else this.sync().catch(() => {});
      this.busy.delete(slug); this.paint();
    };
    try {
      const r = await this.j('/api/connectors/' + encodeURIComponent(slug) + '/link-token', { method: 'POST' });
      if (!r.linkToken) throw Error('服务器没有返回授权链接');
      await this.loadLink();
      const cfg = { linkToken: r.linkToken, onSuccess: () => void end(true), onExit: () => void end(false), onValidationError: () => {} };
      window.AgentHandlerLink.initialize({ ...cfg, onReady: () => { try { window.AgentHandlerLink.openLink(cfg); } catch (e) { toast('打开授权窗口失败：' + describe(e), 'err'); void end(false); } } });
    } catch (e) { toast('连接 ' + this.label(slug) + ' 失败：' + describe(e), 'err'); this.busy.delete(slug); this.paint(); }
  },
  async disconnect(slug) {
    this.busy.add(slug); this.paint();
    try { await this.j('/api/connectors/' + encodeURIComponent(slug), { method: 'DELETE' }); this.setEnabled(slug, false); await this.refresh(true); toast('已断开 ' + this.label(slug)); }
    catch (e) { toast('断开失败：' + describe(e), 'err'); }
    finally { this.busy.delete(slug); this.paint(); }
  },
  logo(c, size = 18) {
    const box = h('span', { class: 'cn-logo', style: { width: size + 'px', height: size + 'px' } });
    if (c.logoUrl) { const img = h('img', { src: c.logoUrl, alt: '', width: size, height: size, referrerpolicy: 'no-referrer' }); img.onerror = () => { img.remove(); box.textContent = (this.label(c.slug)[0] || '?').toUpperCase(); }; box.append(img); }
    else box.textContent = (this.label(c.slug)[0] || '?').toUpperCase();
    return box;
  },
  // 工作区底部的 Connectors 卡片：已连接的列出来，右侧开关 = 本对话发消息时是否启用
  card() {
    const el = h('section', { class: 'cn-card' });
    this.cardEl = el; this.fillCard(el);
    if (!this.at && !this.loading) void this.refresh();
    return el;
  },
  fillCard(el) {
    const on = this.list().filter(c => this.connected(c.slug));
    const head = h('div', { class: 'cn-h' }, h('b', {}, 'Connectors'), h('span', { class: 'grow' }),
      h('button', { class: 'ib xs', title: '添加连接（GitHub / Drive / Docs / Notion / Gmail / Linear / Calendar…）', onclick: () => this.open() }, icon('plus')));
    const rows = on.map(c => h('label', { class: 'cn-row', title: c.description || '' }, this.logo(c, 16), h('span', { class: 'cn-n' }, this.label(c.slug)),
      h('input', { type: 'checkbox', class: 'sw sm', role: 'switch', checked: this.enabled(c.slug) || null, 'aria-label': '在对话里启用 ' + this.label(c.slug), onchange: e => this.setEnabled(c.slug, e.target.checked) })));
    el.replaceChildren(head, ...(rows.length ? [h('div', { class: 'cn-list' }, ...rows)] : []));
  },
  paint() {
    if (this.cardEl?.isConnected) this.fillCard(this.cardEl);
    if (this.dlgBox?.isConnected) this.fillDialog(this.dlgBox);
  },
  open() {
    void this.refresh(true);
    void Dialog.open((box, done) => { box.classList.add('cn-dlg'); this.dlgBox = box; this.dlgDone = done; this.fillDialog(box); });
  },
  fillDialog(box) {
    const done = this.dlgDone;
    const items = this.list().map(c => {
      const st = this.authOf(c.slug), busy = this.busy.has(c.slug), unusable = st === 'unusable', conn = st === 'connected';
      const act = busy ? h('i', { class: 'spin' })
        : conn ? h('span', { class: 'cn-acts' },
          h('input', { type: 'checkbox', class: 'sw', role: 'switch', checked: this.enabled(c.slug) || null, title: '在对话里启用', onchange: e => this.setEnabled(c.slug, e.target.checked) }),
          h('button', { class: 'ib xs', title: '断开连接', onclick: () => this.disconnect(c.slug) }, icon('x')))
        : unusable ? h('span', { class: 'cn-un' }, '不可用') : h('span', { class: 'cn-plus' }, icon('plus'));
      const row = h(conn || unusable || busy ? 'div' : 'button', { class: 'cn-item' + (unusable ? ' off' : '') + (conn ? ' on' : ''), title: unusable ? '这个连接器暂时不能用' : conn ? '' : '连接 ' + this.label(c.slug), onclick: conn || unusable || busy ? null : () => this.connect(c.slug) },
        this.logo(c, 22), h('span', { class: 'cn-t' }, h('b', {}, this.label(c.slug)), h('small', {}, c.description || '')), act);
      return row;
    });
    box.replaceChildren(...[h('div', { class: 'cn-dh' }, h('div', { class: 'dlg-t' }, 'Connectors'), h('span', { class: 'grow' }), h('button', { class: 'ib', title: '关闭', onclick: () => { this.dlgBox = null; done?.(null); } }, icon('x'))),
      this.err ? h('p', { class: 'note' }, '读取失败：' + this.err) : null,
      this.loading && !this.catalog ? h('p', { class: 'note' }, h('i', { class: 'spin' }), ' 读取中…') : null,
      h('div', { class: 'cn-items' }, ...items),
      h('p', { class: 'note cn-foot' }, '授权在 Merge（官方使用的连接服务）的弹窗里完成；连接后打开开关，在对话里提到应用名就能用。')].filter(Boolean));
  }
};

// ---- titles.js ----
