    const ipb = this.$('[data-a="ipok"]'), ipOn = !this.target && !active && Gacha.ipLimited(); ipb.hidden = !ipOn; if (!ipOn) { ipb.disabled = false; ipb.textContent = '我已更换 IP'; }
    this.$('[data-a="captcha"]').hidden = !!this.target || !Gacha.capOffer();
