    const logBox = this.$('[data-s="log"]'), rows = (st?.attempts || []).slice(-30).reverse(), key = JSON.stringify(rows.map(a => [a.no, a.verdict, a.model, a.archived, a.note, a.fixed, a.fingerprint?.skipped, a.phase, a.step, a.pct]));
    logBox.hidden = !rows.length;
