          if (!this.target && a.verdict === 'skipped' && /reCAPTCHA/.test(a.note || '')) { d.classList.add('gpCapRow'); d.title = '点这里完成人机验证（官方复选框，由你自己勾选）'; d.onclick = () => Gacha.busy() ? Gacha.solveCaptcha().catch(err => this.say(err.message, true)) : null; }
