        if (!d.src.includes(p.line)) d.src.push(p.line);
        if ((p.ip || p.chain) && !d.ips[p.line]) d.ips[p.line] = { ip: p.host, port: p.port, src: '', ...(p.chain ? { chain: p.chain } : {}) };
