        const keys = this.entries().filter(([k, e]) => srcs.has(e.src) && !e.gone && !this.banned(k) && !this.owner(k) && (e.ok == null || (e.ok === true && e.loc === cc && now() - (e.at || 0) > 3 * 3600e3))).map(([k]) => k).sort(() => Math.random() - .5).slice(0, 8);
