        const isBad = IPRep.risky(k, e) || (Boolean(e.src) && Boolean(IPRep.impure?.(k, e)));
        if (!isBad) continue;
        const low = k.toLowerCase(), eg = String(e.eg || '').trim().toLowerCase();
        d.ban[low] = now(); d.drop[k] = now(); d.drop[low] = now();
