          if(sw)sw.done((exit?'出口 '+exit+' · ':'')+(r.ms>=1000?(r.ms/1000).toFixed(1)+' s':r.ms+' ms'));
          else if(typeof toast==='function')toast('✓ 连接已更新 · '+modeLabels[wanted]+' · '+effective+(saved.proxyIp?' · '+saved.proxyIp:''));
