      const ip=IP.ip||'',f=flagOf(IP.loc||cc)||'🌐',ms=IP.rtt||IP.liveFor?.(a.proxyIp)||0;
      const rttTimeout=Boolean(IP.rttFail>0&&!IP.quietFail?.());
