    if (T?.color) { wrap.style.setProperty('--bg', T.color); if (T.symbolColor) wrap.style.setProperty('--fg', T.symbolColor); }
    const body = document.createElement('div'); body.className = 'anc-r' + (mob ? ' m' : '');
