      if (a.dataset.ancT !== hit.label) a.dataset.ancT = hit.label;
      if (hit.vid) { icon(hit.vid); if (a.dataset.ancV !== hit.vid) a.dataset.ancV = hit.vid; } else delete a.dataset.ancV;
